import React, { useRef, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { FormattedMessage, useIntl } from 'react-intl';

import { InformationIcon } from '@dynatrace/strato-icons';

import { _useInternalTimeframeSelectorContext } from './hooks/useInternalTimeframeSelectorContext.js';
import { useTimeframeSelectorContext } from './hooks/useTimeframeSelectorContext.js';
import {
  timeframeSelectorFormCSS,
  timeframeSelectorHintIconCSS,
} from './TimeframeSelector.sty.js';
import { _isOutsideRange } from './utils/timeframe-selection.js';
import { Button } from '../../buttons/button/Button.js';
import {
  TimeDetails,
  Timeframe,
  type TimeValue,
} from '../../core/types/time.js';
import { parseTime } from '../../core/utils/timeParser.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { DatePicker } from '../date-picker/DatePicker.js';
import { DatePickerValue } from '../date-picker/types/change-event.js';
import { FormField } from '../forms-core/components/form-field/FormField.js';
import { Hint } from '../forms-core/components/hint/Hint.js';
import { Label } from '../forms-core/components/label/Label.js';
import {
  _getFormattedMinMax,
  _parseTime,
  _parseValue,
  messages,
} from '../forms-core/time/timeParser.js';
import { _useInputHint } from '../hooks/useInputHint.js';

/**
 * Reevaluate expression based time details to have latest timestamps
 */
function reevaluate(timeDetails: TimeValue | null): Date | null {
  if (!timeDetails) {
    return null;
  }

  // fixed time, nothing to reevaluate
  if (timeDetails.type === 'iso8601') {
    return new Date(timeDetails.absoluteDate);
  }

  // in case of an expression, get the latest timestamps
  const parsedTime = _parseTime(timeDetails.value)?.absoluteDate;
  return parsedTime ? new Date(parsedTime) : null;
}

/** Check if the from dates are in the right order. */
function isInvalidOrder(fromValue?: string, toValue?: string): boolean {
  if (!fromValue || !toValue) {
    return false;
  }

  const parsedFrom = _parseTime(fromValue);
  const parsedTo = _parseTime(toValue);

  // check early if the same value has been entered in both fields (timestamps will not be equal)
  if (parsedFrom && parsedTo && parsedFrom.value === parsedTo.value) {
    return true;
  }

  /** reevaluate date-picker inputs for comparison */
  const from = reevaluate(parsedFrom)?.getTime();
  const to = reevaluate(parsedTo)?.getTime();

  return !!from && !!to && to <= from;
}

/**
 * Custom Timeframe Selector component used inside the overlay.
 */
export const CustomTimeframeSelector = () => {
  const intl = useIntl();
  const { details, onChange } = useTimeframeSelectorContext();
  const { min, max, precision } = _useInternalTimeframeSelectorContext();

  const { from, to } = _parseValue(details, true);

  const initialFrom = () =>
    from
      ? {
          normalized: from?.value.replace('now()', 'now'), // TODO remove the replace as soon as we switch to the DateTimeRangePicker, which would support now()
          date: new Date(from.absoluteDate),
          type: from.type,
        }
      : null;
  const initialTo = () =>
    to
      ? {
          normalized: to?.value.replace('now()', 'now'),
          date: new Date(to.absoluteDate),
          type: to.type,
        }
      : null;

  const fromButtonRef = useRef<HTMLButtonElement>(null);
  const toButtonRef = useRef<HTMLButtonElement>(null);

  const [fromValue, setFromValue] = useState<TimeDetails | null>(initialFrom);
  const [toValue, setToValue] = useState<TimeDetails | null>(initialTo);

  const {
    handleSubmit,
    setValue,
    reset,
    getValues,
    trigger,
    formState,
    control,
  } = useForm<Timeframe>({
    mode: 'onSubmit',
    defaultValues: {
      from: initialFrom()?.normalized ?? '', // initialize form values to prevent showing required error messages incorrectly (if from and to are initialized)
      to: initialTo()?.normalized ?? 'now',
    },
  });

  const ariaLabelApplyButton = intl.formatMessage({
    defaultMessage: 'Apply custom timeframe',
    id: 'WgSgLoZuHi+qKpWl',
    description:
      'Aria label for the apply button of the custom timeframe selector',
  });

  const invalidFromIsoDate = intl.formatMessage(
    {
      defaultMessage:
        "The 'from' field should have this format: 2023-02-23 00:00{precision}.",
      id: 'R9fBmDyleRAV8ait',
      description: 'Timeframe selector invalid from field error hint.',
    },
    {
      precision: `${precision === 'seconds' ? ':00' : ''}`,
    },
  );

  const invalidToIsoDate = intl.formatMessage(
    {
      defaultMessage:
        "The 'to' field should have this format: 2023-03-23 00:00{precision}.",
      id: 'wnfubvmP4G5oINM7',
      description: 'Timeframe selector invalid from field error hint.',
    },
    {
      precision: `${precision === 'seconds' ? ':00' : ''}`,
    },
  );

  const invalidFromExpression = intl.formatMessage({
    defaultMessage: "The 'from' field is invalid.",
    id: 'UFdUOJclsfKBOdgu',
    description:
      'Timeframe selector invalid from field error hint shown for relative timeframes.',
  });

  const invalidToExpression = intl.formatMessage({
    defaultMessage: "The 'to' field is invalid.",
    id: 'pfSXERwOemwyXjWx',
    description:
      'Timeframe selector invalid to field error hint shown for relative timeframes.',
  });

  const requiredFrom = intl.formatMessage({
    defaultMessage: "The 'from' field is required.",
    id: 'VlyElrRtYeguIlZS',
    description: 'Timeframe selector required from field error hint.',
  });

  const requiredTo = intl.formatMessage({
    defaultMessage: "The 'to' field is required.",
    id: 'd7CsKWrzLvzuObN6',
    description: 'Timeframe selector required to field error hint.',
  });

  const invalidOrderMessage = intl.formatMessage(messages.invalidOrder);

  const hintText = intl.formatMessage(
    messages.outsideRange,
    _getFormattedMinMax(min, max, precision),
  );

  /** Function that checks if the field is valid and returns an error message if invalid. */
  function isInvalidInput(value: string, fieldType: 'from' | 'to') {
    if (!value) {
      return true;
    }

    const parsedValue = _parseTime(value);

    const invalidIsoMessage =
      fieldType === 'from' ? invalidFromIsoDate : invalidToIsoDate;
    const invalidExpressionMessage =
      fieldType === 'from' ? invalidFromExpression : invalidToExpression;
    const invalidMessage =
      parsedValue?.type === 'iso8601'
        ? invalidIsoMessage
        : invalidExpressionMessage;

    return !!parsedValue || invalidMessage;
  }

  /** Handle form submission. */
  function handleFormSubmit(_data: Timeframe) {
    /** parse date-picker inputs to have latest expression values on form submission */
    const from = _parseTime(getValues('from'));
    const to = _parseTime(getValues('to')) ?? _parseTime('now');

    if (from) {
      setValue('from', from.value);
      setFromValue({
        date: new Date(from.absoluteDate),
        normalized: from.value,
        type: from.type,
      });
    }
    if (to) {
      setValue('to', to.value);
      setToValue({
        date: new Date(to.absoluteDate),
        normalized: to.value,
        type: to.type,
      });
    }

    // Check isInvalidOrder instead of formState.isValid, since the validation, even if manually triggered here, would happen at a later point
    if (from && to && !isInvalidOrder(from.value, to.value)) {
      onChange({
        from,
        to,
      });
    }
  }

  const { hintProps } = _useInputHint({ hasError: false });

  return (
    <form
      onReset={() => reset()}
      noValidate
      className={timeframeSelectorFormCSS}
      onSubmit={handleSubmit(handleFormSubmit)}
    >
      <Flex flexDirection="column" gap={16}>
        <Flex flexDirection="column" gap={4}>
          <Flex>
            <Controller
              name="from"
              control={control}
              rules={{
                required: {
                  value: true,
                  message: requiredFrom,
                },
                validate: {
                  isInvalidOrder: () =>
                    !isInvalidOrder(getValues('from'), getValues('to')),
                  isInvalidInput: (value: string) =>
                    isInvalidInput(value, 'from'),
                  isOutsideRange: () =>
                    !_isOutsideRange(
                      { from: getValues('from'), to: getValues('to') },
                      min,
                      max,
                    ),
                },
              }}
              render={({ field, fieldState: { error } }) => (
                <FormField
                  required
                  style={{ minWidth: 0, flexGrow: 1, maxWidth: '50%' }}
                >
                  <Label>
                    {intl.formatMessage({
                      defaultMessage: 'From',
                      id: 'oqdWoMVh8up7+v3B',
                      description:
                        'The label used for the "from" datepicker input.',
                    })}
                  </Label>
                  <DatePicker
                    showTime={true}
                    fillUpTime={false}
                    precision={
                      precision === 'milliseconds' ? 'seconds' : precision // TODO: remove mapping when replacing the DatePicker with the DateTimeRangePicker, as it doesn't support milliseconds
                    }
                    buttonRef={fromButtonRef}
                    onCalendarValueChange={() => trigger()}
                    onInputValueChange={(value) => setValue('from', value)}
                    onInputBlur={() =>
                      formState.errors.to?.type === 'isInvalidOrder' &&
                      trigger()
                    } // fixes an edge case showing 2 errors when the order is invalid after submitting and then the input is cleared and blurred - it should only show the required error
                    controlState={{
                      state: error ? 'error' : 'valid',
                      hint: error?.message,
                    }}
                    {...field}
                    value={fromValue?.normalized ?? null}
                    onChange={(value: DatePickerValue) => {
                      const parsedTime = parseTime(value?.details?.normalized);
                      setFromValue(parsedTime);
                      field.onChange(value.value);
                    }}
                  />
                </FormField>
              )}
            />
            <Controller
              name="to"
              control={control}
              rules={{
                required: {
                  value: true,
                  message: requiredTo,
                },
                validate: {
                  isInvalidOrder: () =>
                    !isInvalidOrder(getValues('from'), getValues('to')),
                  isInvalidInput: (value: string) =>
                    isInvalidInput(value, 'to'),
                  isOutsideRange: () =>
                    !_isOutsideRange(
                      { from: getValues('from'), to: getValues('to') },
                      min,
                      max,
                    ),
                },
              }}
              render={({ field, fieldState: { error } }) => (
                <FormField
                  required
                  style={{ minWidth: 0, flexGrow: 1, maxWidth: '50%' }}
                >
                  <Label>
                    {intl.formatMessage({
                      defaultMessage: 'To',
                      id: 'vZgaCscTo/b7U0Y2',
                      description:
                        'The label used for the "to" datepicker input.',
                    })}
                  </Label>
                  <DatePicker
                    showTime={true}
                    fillUpTime={true}
                    precision={
                      precision === 'milliseconds' ? 'seconds' : precision // TODO: remove mapping when replacing the DatePicker with the DateTimeRangePicker, as it doesn't support milliseconds
                    }
                    buttonRef={toButtonRef}
                    onCalendarValueChange={() => trigger()}
                    onInputValueChange={(value: string) =>
                      setValue('to', value)
                    }
                    onInputBlur={() =>
                      formState.errors.from?.type === 'isInvalidOrder' &&
                      trigger()
                    }
                    controlState={{
                      state: error ? 'error' : 'valid',
                      hint: error?.message,
                    }}
                    {...field}
                    value={toValue?.normalized ?? null}
                    onChange={(value: DatePickerValue) => {
                      const parsedTime = parseTime(value?.details?.normalized);
                      setToValue(parsedTime);
                      field.onChange(value.value);
                    }}
                  />
                </FormField>
              )}
            />
          </Flex>
          {formState.errors?.from?.type === 'isInvalidOrder' && (
            <Hint hasError>{invalidOrderMessage}</Hint>
          )}
          {min && max && (
            <Flex gap={4}>
              {formState.errors?.from?.type !== 'isOutsideRange' && (
                <InformationIcon
                  size="small"
                  className={timeframeSelectorHintIconCSS}
                />
              )}
              <Hint
                hasError={formState.errors?.from?.type === 'isOutsideRange'}
                {...hintProps}
              >
                {hintText}
              </Hint>
            </Flex>
          )}
        </Flex>

        {/*
              Add an onClick handler that submits the form instead of relying on the form's onSubmit handler.
              This is done to avoid the bubbling up of the form submit event to outer forms.
              Attempts of using event.stopPropagation and event.preventDefault ended with failure
              in stopping the bubbling up of the submit event.
              The type 'submit' is kept in order to allow the user to submit the form on hitting enter on any of the inputs here.
              In the end, the 'Submit' event is now replaced with a 'Click' event which doesn't bubble up.
               */}
        <Button
          color="primary"
          variant="accent"
          type="submit"
          aria-label={ariaLabelApplyButton}
          style={{ alignSelf: 'end' }}
          onClick={handleSubmit(handleFormSubmit)}
        >
          <FormattedMessage
            defaultMessage="Apply"
            id="Np6+N27mrjvIJEls"
            description="Shown for the apply button of the timeframe selector."
          />
        </Button>
      </Flex>
    </form>
  );
};

CustomTimeframeSelector['displayName'] = 'CustomTimeframeSelector';
